export async function evaluatePersistentResearchPolicy(input:{policyId:string;baselinePolicyId?:string;datasetCutoff:string;minimumAssignments?:number;actor:string}){if(!input.baselinePolicyId)throw new Error('BASELINE_POLICY_REQUIRED');const replay=await runPersistentResearchPolicyReplay({policyId:input.policyId,baselinePolicyId:input.baselinePolicyId,datasetCutoff:input.datasetCutoff,actor:input.actor}),artifact={policyId:input.policyId,baselinePolicyId:input.baselinePolicyId,cutoff:new Date(input.datasetCutoff).toISOString(),replayId:replay.replayId,datasetId:replay.datasetId,metrics:{candidate:replay.candidate,baseline:replay.baseline,incrementalDifference:replay.incrementalDifference,confidenceInterval:replay.confidenceInterval,segmentGuardrails:replay.segmentGuardrails},decision:replay.decision,reasonCodes:replay.reasonCodes},key=researchChecksum(artifact),db=await getDb(),result=await db.query(`INSERT INTO persistent_research_policy_evaluations(evaluation_key,policy_id,baseline_policy_id,dataset_cutoff,metrics,decision,reason_codes,artifact_checksum,evaluated_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) ON CONFLICT(evaluation_key) DO NOTHING RETURNING *`,[key,input.policyId,input.baselinePolicyId,artifact.cutoff,JSON.stringify(artifact.metrics),artifact.decision,JSON.stringify(artifact.reasonCodes),researchChecksum(artifact),input.actor]);return result.rows[0]||{evaluationKey:key,duplicate:true,decision:artifact.decision};}
